/* ---- the clear-attach fragment shader (driver: pvr_usc_clear_fs_blob.h) ----
 * USC "clear-attach" pixel shader for the BXS-4-64 (BVNC 36.53.104.796): what
 * a clear/fill render binds to output a solid colour to the render target.
 *
 * VERIFIED: captured from a real build of Mesa 26.2.1's PowerVR (pvr) + PCO
 * compiler by calling pvr_uscgen_clear_attach(pco_ctx, &props)
 * (src/imagination/vulkan/pvr_usc.c:1283) with the single-dword colour-clear
 * props (dword_count = 1, offset = 0, uses_tile_buffer = false): shader #0 of
 * the 20-entry clear-attach table pvr_device_init_clear_attachment_programs()
 * builds.
 *
 * HOW THE OUTPUT COLOUR IS SUPPLIED (critical for the feeding PDS): the shader
 * reads the clear colour from SHARED REGISTER 0 (sh0) and writes it to
 * pixel-output register 0 (po0); in the NIR it is
 * nir_load_preamble(base = PVR_CLEAR_ATTACH_DATA_DWORD0 + u) with
 * PVR_CLEAR_ATTACH_DATA_DWORD0 == 0 (pvr_iface.h). So the colour-upload PDS
 * "texture/uniform" program must DMA the 32-bit packed clear colour into sh0
 * before the USC runs (it loads _PVR_CLEAR_ATTACH_DATA_COUNT dwords starting
 * at sh0; only sh0 is consumed). The colour is one dword in the render
 * target's pixel format (already pbe/format-packed by the caller).
 *
 * PCO final IR (single instruction group):
 *     block B0:
 *       0000: { s0 = sh0, is4 = ft0 p0: mbyp ft0, s0; w0 = po0 }.olchk.end
 * i.e. move shared reg 0 through the ALU bypass to pixel output 0, with
 * output-line-check, end of program. */
pub const PVR_USC_CLEAR_FS_TEMPS: u32 = 0;
pub const PVR_USC_CLEAR_FS_DWORDS: usize = 4;
pub const PVR_USC_CLEAR_FS_SIZE_BYTES: usize = 16;
/// The clear colour is consumed from shared register 0 (sh0).
pub const PVR_USC_CLEAR_FS_COLOR_SHARED_REG: u32 = 0;

/// 16 bytes = 4 dwords, little-endian.
pub static PVR_USC_CLEAR_FS_WORDS: [u32; PVR_USC_CLEAR_FS_DWORDS] = [0x87808a38, 0x00000880, 0xfff32000, 0xffffffff];

/// Byte view (identical data), for upload paths that want bytes.
#[rustfmt::skip]
pub static PVR_USC_CLEAR_FS_BYTES: [u8; PVR_USC_CLEAR_FS_SIZE_BYTES] = [
    0x38, 0x8a, 0x80, 0x87,
    0x80, 0x08, 0x00, 0x00,
    0x00, 0x20, 0xf3, 0xff,
    0xff, 0xff, 0xff, 0xff,
];

